    bring: ['king', 'sing', 'ring', 'thing'],
    // ── tier 3+ syllabic family ─────────────────────────────────────────────
    // NOTE: 'apple'/'happy' do NOT rhyme (different unstressed endings) and
    // 'maple' is not a KNOWN_WORD_SET word — the syllabic family is -unny.
    sunny: ['funny'],
    funny: ['sunny']
